const [assigned, setAssigned] = useState(false)
const [channels, setChannels] = useState(['email'])const allOn = channels.length === CHANNELS.length
const someOn = channels.length > 0 && !allOn<Stack gap={4}>
  <Checkbox
    label="Email me when a review is assigned"
    checked={assigned}
    onChange={(e) => setAssigned(e.target.checked)}
  />

  <Checkbox
    label="All channels"
    checked={allOn}
    indeterminate={someOn}
    onChange={(e) => { setChannels(e.target.checked ? CHANNELS.map((c) => c.value) : []) }}
  />
  <CheckboxGroup
    label="How should we reach you?"
    options={CHANNELS}
    value={channels}
    onChange={setChannels}
  />

  <Stack gap={2}>
    <SectionLabel as="h3">In a filter panel</SectionLabel>
    <Checkbox label="Only mine" size="sm" checked onChange={() => undefined} />
    <Checkbox label="Archived" size="sm" checked={false} onChange={() => undefined} />
  </Stack>
</Stack>
